// LA BIBLIOTHÈQUE DE PROMPTS DE LA COMMUNAUTÉ.
//
// Des prompts originaux, écrits pour DojoBuro, rangés par thème. Chacun est
// prêt à copier : ce que la personne remplit est entre [CROCHETS]. Chacun suit
// les mêmes bonnes pratiques (un rôle et un contexte, une tâche, des
// contraintes, un format de réponse, des questions ou des hypothèses
// annoncées, aucun fait inventé, une vérification), avec des structures
// volontairement variées pour ne pas apprendre un seul gabarit.
//
// Juridique, finance et RH rappellent qu'un professionnel qualifié relit le
// résultat : un prompt ne remplace pas un avis.
import { B, type Bi } from '../bilingual'

export interface PromptCategory { id: string; label: Bi }

export interface LibraryPrompt {
  /** identifiant unique, préfixé par la catégorie */
  id: string
  /** l'identifiant d'une PromptCategory */
  category: string
  title: Bi
  /** à quoi il sert, en une phrase */
  use: Bi
  /** le prompt lui-même, prêt à copier, avec des [CHAMPS] à remplir */
  prompt: Bi
  level: 'debutant' | 'intermediaire' | 'avance'
  tags: string[]
}

